import * as T from './vendor/three.module.min.js';
// Six independent clocks. No particles, physics solver or per-frame mesh uploads.
export function createGardenSprinklers85(scene,texture,onFaceSpray){const root=new T.Group();root.name='Intermittent hidden plant irrigation';scene.add(root);let seed=0x85717;const rnd=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
 const records=[],sources=[[[7.83,1.65,-2.79],[6.9,2.65,-2.79],[5.85,.05,-2.94]],[[7.80,.79,1.2],[7.15,1.38,1.3],[6.35,.04,1.0]],[[-7.86,1.2,-3.0],[-7.2,1.8,-3.0],[-6.41,.04,-3.2]],[[-7.70,.72,-6.5],[-6.6,1.6,-6.5],[-5.74,.06,-6.6]],[[3.0,1.02,-9.38],[3.1,1.9,-8.6],[3.4,.07,-7.8]],[[-2.2,.8,-9.4],[-2.6,1.6,-8.5],[-2.8,.05,-7.1]]];
 for(let j=0;j<sources.length;j++){const pts=sources[j].map(p=>new T.Vector3(...p)),curve=new T.QuadraticBezierCurve3(...pts),pos=[],uv=[],ix=[];for(let i=0;i<=24;i++){const p=curve.getPoint(i/24);for(const s of[-1,1]){pos.push(p.x,p.y,p.z+s*(.0035+i*.00009));uv.push(s<0?0:1,1-i/24);}if(i<24){const a=i*2;ix.push(a,a+1,a+2,a+1,a+3,a+2);}}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(pos,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(ix);g.computeVertexNormals();const map=texture.clone();map.wrapS=map.wrapT=T.RepeatWrapping;map.repeat.set(1,4);map.needsUpdate=true;const mat=new T.MeshBasicMaterial({map,color:0xc5f1f4,transparent:true,opacity:.58,side:T.DoubleSide,depthWrite:false});const stream=new T.Mesh(g,mat),group=new T.Group();group.add(stream);root.add(group);const mist=[];for(let i=0;i<4;i++){const m=new T.SpriteMaterial({map:texture,color:0xc6dce0,transparent:true,opacity:0,depthWrite:false,rotation:rnd()*6.28}),s=new T.Sprite(m);s.position.copy(j===0?new T.Vector3(6.82,1.7,-2.8):pts[2]).add(new T.Vector3((rnd()-.5)*.25,.09+i*.10,(rnd()-.5)*.25));s.scale.setScalar(.33+i*.08);group.add(s);mist.push(s);}group.visible=false;records.push({group,stream,map,mist,next:4.5+j*3.2+rnd()*7,until:0,active:false,phase:rnd()*6});}
 let last=0;return{root,records,update(t){if(t<last)records.forEach((r,i)=>{r.next=t+2+i;r.active=false;r.group.visible=false;});last=t;for(let i=0;i<records.length;i++){const r=records[i];if(!r.active&&t>=r.next){r.active=true;r.until=t+1.35+rnd()*2.1;r.group.visible=true;if(i===0)onFaceSpray?.(t+.13);}if(r.active&&t>r.until){r.active=false;r.group.visible=false;r.next=t+9+rnd()*21;}if(r.active){r.map.offset.y=-t*2.7;for(let j=0;j<r.mist.length;j++){const s=r.mist[j];s.material.opacity=.09+.08*Math.sin(t*6+r.phase+j)**2;s.scale.setScalar(.36+j*.14+.08*Math.sin(t*3+j));}}}},dispose(){root.traverse(o=>{o.geometry?.dispose();if(o.material)o.material.dispose();});records.forEach(r=>r.map.dispose());root.removeFromParent();}};}
